 if(deadTimer<=0){const nx=clamp(player.position.x+move.x*speed*dt,-245,245),nz=clamp(player.position.z+move.z*speed*dt,-255,245);const climb=groundHeight(nx,nz)-groundHeight(player.position.x,player.position.z);const climbLimit=Math.abs(nx-riverX(nz))<15?1.6:.32;if(climb<Math.max(.025,speed*dt*climbLimit)||progress.tiers[1]>=4){const candidate=new T.Vector3(nx,groundHeight(nx,nz),nz);collideWalls(candidate,2.3);player.position.x=candidate.x;player.position.z=candidate.z;}else if(move.length()>.1&&elapsed%3<dt)notify('PISTONS IV · CLIFF CLAWS');}
 player.position.y=groundHeight(player.position.x,player.position.z);player.rotation.y=yaw;walkPhase+=dt*speed*.65*move.length();let {arms,legs}=player.userData;const walk=Math.sin(walkPhase);for(let i=0;i<2;i++){let target=blocking?-1.05:walk*(i===0?-.2:.2)*move.length();if(swingTime>0&&i===attackSide)target=-Math.sin((1-swingTime/.42)*Math.PI)*1.8;if(grapple&&i===0)target=-1.2;arms[i].rotation.x=T.MathUtils.lerp(arms[i].rotation.x,target,1-Math.exp(-dt*20));legs[i].rotation.x=walk*(i===0?.35:-.35)*move.length();}player.userData.high.rotation.z=charge>0?.1:walk*.015*move.length();player.position.y+=Math.abs(walk)*.12*move.length();const foot=Math.floor(walkPhase/Math.PI);if(foot!==previousFoot&&move.length()>.1){previousFoot=foot;sound('step',charge>0?1.5:1);burst(player.position.clone(),3);shake=Math.max(shake,.035);if(inRiver)burst(player.position.clone().setY(.4),5);}if(mouseDown)punch();playerContact.position.set(player.position.x,player.position.y+.05,player.position.z);playerContact.scale.setScalar(1);
 if(grapple){const e=grapple.enemy;grapple.time+=dt;e.stun=1;const target=player.position.clone().addScaledVector(f,9);e.g.position.lerp(target,1-Math.exp(-dt*8));e.knock.set(0,0,0);let a=cable.geometry.attributes.position;a.setXYZ(0,player.position.x-1.5,player.position.y+7,player.position.z);a.setXYZ(1,e.g.position.x,e.g.position.y+7,e.g.position.z);a.needsUpdate=true;cable.geometry.computeBoundingSphere();cable.visible=true;if(grapple.time>2.5)releaseGrapple(true);}
