function updateStructures(dt){for(const s of structures){if(!s.dead||s.fall>=Math.PI/2)continue;s.fall=Math.min(Math.PI/2,s.fall+dt*(.5+s.fall*1.3));s.g.quaternion.setFromAxisAngle(new T.Vector3(s.dir.z,0,-s.dir.x).normalize(),s.fall);if(s.fall>.3){const tip=new T.Vector3(s.x+s.dir.x*Math.sin(s.fall)*s.h,s.y+Math.cos(s.fall)*s.h*.5,s.z+s.dir.z*Math.sin(s.fall)*s.h);for(const e of [...enemies])if(!s.hit.has(e.id)&&dist(e.g.position,tip)<7+s.h*.15){s.hit.add(e.id);hurtEnemy(e,s.isTower?90:35,s.dir,24,true);}if(s.fall===Math.PI/2){burst(tip,30,true);shake=.8;sound('break');}}}}
function updateFoundries(dt){passive+=dt;repairTimer+=dt;for(let i=0;i<forts.length;i++){let fort=forts[i],owned=progress.captured.includes(i)&&mode==='roam';fort.beacon.material=owned?materials.blue:materials.warn;fort.beacon.scale.y=owned?1.5:1;const fd=dist(player.position,{x:fort.x,z:fort.z});fort.base.visible=fd<340;fort.high.visible=fd<(qualityName==='low'?72:qualityName==='med'?140:240);fort.low.visible=!fort.high.visible;
 if(mode!=='roam')continue;let nearby=dist(player.position,{x:fort.x,z:fort.z});const guards=enemies.filter(e=>Math.hypot(e.g.position.x-fort.x,e.g.position.z-fort.z)<28);
 if(!owned&&nearby<13&&guards.length===0){progress.captured.push(i);metrics.captures++;progress.cash+=75+fort.level*30;hp=Math.min(maxHP(),hp+60);notify('FOUNDRY CAPTURED');sound('upgrade');save();}
 if(owned){fort.raid-=dt;if(fort.raid<=0){fort.raid=90;if(enemies.length<8){const a=rand()*Math.PI*2;spawn(fort.x+Math.sin(a)*35,fort.z+Math.cos(a)*35,fort.level+1);notify('⚙ UNDER ATTACK');}}if(guards.length&&nearby>45){fort.raid-=dt*2;if(fort.raid<35){progress.captured=progress.captured.filter(n=>n!==i);fort.raid=80;notify('FOUNDRY CONTESTED');save();}}if(nearby<17&&repairTimer>=2)hp=Math.min(maxHP(),hp+4+progress.tiers[4]);}}
 if(mode==='roam'&&passive>=5){passive=0;let gain=progress.captured.length*(3+progress.tiers[4]*2)+(specialized(4,0)?progress.captured.length*4:0);if(gain){progress.cash+=gain;metrics.income+=gain;save();}}if(repairTimer>=2){repairTimer=0;if(specialized(4,1))hp=Math.min(maxHP(),hp+3+progress.tiers[4]);}}
function updateRumble(dt){if(mode!=='rumble'||rumbleOver)return;rumbleTime=Math.max(0,rumbleTime-dt);rumbleSpawn+=dt;if(rumbleSpawn>=12){rumbleSpawn=0;for(let i=0;i<2;i++){let a=rand()*Math.PI*2;spawn(Math.sin(a)*35,-15+Math.cos(a)*35,Math.min(4,Math.floor((90-rumbleTime)/22)));}const s=structures.filter(s=>!s.dead&&Math.hypot(s.x,s.z)<65)[0];if(s)collapse(s,new T.Vector3(rand()-.5,0,rand()-.5).normalize());}
 if(dist(player.position,{x:0,z:-15})>70){let inward=new T.Vector3(-player.position.x,0,-15-player.position.z).normalize();player.position.addScaledVector(inward,dt*24);burst(player.position,3);}
 if(rumbleTime<=0){rumbleOver=true;mouseDown=false;keys={};$('resultScore').textContent=score;$('result').hidden=false;mainProgress.best=Math.max(mainProgress.best,score);$('resultBest').textContent='BEST · '+mainProgress.best;try{localStorage.setItem('brass-colossus-v2',JSON.stringify(mainProgress));}catch{}document.exitPointerLock?.();}}
function update(dt){if(rumbleOver)return;elapsed+=dt;if(deadTimer>0){deadTimer-=dt;if(deadTimer<=0){hp=maxHP();steam=100;player.position.set(0,groundHeight(0,8),8);progress.cash=Math.max(0,progress.cash-15);notify('PRESSURE RESTORED');save();}}
 updatePlayer(dt);updateEnemies(dt);updateStructures(dt);updateFoundries(dt);updateRumble(dt);for(const q of [...spawnQueue]){q.delay-=dt;if(q.delay<=0){spawnQueue.splice(spawnQueue.indexOf(q),1);if(q.session===session&&!rumbleOver){if(mode==='rumble'){let a=rand()*Math.PI*2;spawn(player.position.x+Math.sin(a)*28,player.position.z+Math.cos(a)*28,q.tier);}else spawn(q.x+(rand()-.5)*20,q.z+(rand()-.5)*20,q.tier);}}}
 if(hp<=0&&deadTimer<=0){deadTimer=2;metrics.rebuilds++;releaseGrapple(false);notify('REBUILDING');mouseDown=false;}hp=clamp(hp,0,maxHP());}
function projectLabel(p,el){let v=p.clone().project(camera);if(v.z>1||v.z<0||Math.abs(v.x)>1.2||Math.abs(v.y)>1.2){el.hidden=true;return;}el.hidden=false;el.style.left=(v.x*.5+.5)*innerWidth+'px';el.style.top=(-v.y*.5+.5)*innerHeight+'px';}
const fortLabels=forts.map(()=>{let el=document.createElement('div');el.className='worldLabel';$('worldLabels').append(el);return el;});
function updateLabels(){for(const e of enemies){if(dist(player.position,e.g.position)>65){e.label.hidden=true;continue;}projectLabel(e.g.position.clone().add(new T.Vector3(0,(13+e.tier)*e.g.scale.x,0)),e.label);e.label.querySelector('.ebar i').style.width=Math.max(0,e.hp/e.max*100)+'%';e.label.querySelector('.windup').textContent=e.wind>0?'⚠':'';}forts.forEach((f,i)=>{const owned=progress.captured.includes(i)&&mode==='roam',el=fortLabels[i];if(mode==='rumble'||Math.hypot(player.position.x-f.x,player.position.z-f.z)<20){el.hidden=true;return;}el.style.color=owned?'#70d6ed':'#edc58d';el.innerHTML=(owned?'⚙':'♜')+'<small>'+Math.round(Math.hypot(player.position.x-f.x,player.position.z-f.z))+'m</small>';projectLabel(new T.Vector3(f.x,height(f.x,f.z)+18,f.z),el);});}
function updateUI(){const v=progress.tiers[branch],b=branches[branch];$('hp').style.width=hp/maxHP()*100+'%';$('steam').style.width=steam+'%';$('healthLabel').textContent=Math.ceil(hp)+' / '+maxHP();$('guardState').textContent=grapple?'⚓ ATTACHED':blocking?(parryWindow>0?'◇ PARRY':'⬡ BRACED'):charge>0?'➜ CHARGING':'● READY';$('guardState').style.color=parryWindow>0?'#ffda8c':'#74c8d9';$('salvage').textContent='◆ '+Math.floor(progress.cash);$('branch').textContent=b.name;$('level').textContent=v+' / 6';$('tierDots').innerHTML=Array.from({length:6},(_,i)=>'<i class="'+(i<v?'filled':'')+'"></i>').join('');$('benefit').textContent=b.benefit;for(let n=0;n<2;n++){const el=$('choice'+n);el.textContent=b.choices[n]+(v>=3&&progress.choices[branch]===n?' ◇':'');el.classList.toggle('active',progress.choices[branch]===n);el.title=b.description[n];}const locked=v>=6;$('upgrade').disabled=locked;$('upgrade').innerHTML=locked?'CHASSIS COMPLETE':'<kbd>F</kbd> Fit machinery <span>◆ '+cost()+'</span>';$('unlock').textContent=branch===1?(v<2?'II · Long lunge':v<4?'IV · Cliff claws':b.description[progress.choices[branch]]):branch===2&&v<2?'II · Riverbed traction':v<3?'III · Commit steam system':b.description[progress.choices[branch]];$('kills').textContent=mode==='rumble'?'⚔ '+score+' / '+Math.ceil(rumbleTime)+'s':'⚔ '+progress.kills;$('workshops').textContent='⚙ '+progress.captured.length+' / 4';$('plate').textContent='⬡ '+(plateUses||'—');$('rank').textContent='MK '+(1+Math.floor(progress.tiers.reduce((a,b)=>a+b,0)/3));$('region').textContent=mode==='rumble'?'FOUNDRY RUMBLE':player.position.z<-170?'MOUNTAIN CITADELS':player.position.x<-70&&player.position.z<-65?'CANYON FOUNDRY':player.position.x>45?'FLOODED RUINS':'SUNFALL VALLEY';let bearing=((yaw*180/Math.PI)%360+360)%360;$('bearing').textContent=['N','NW','W','SW','S','SE','E','NE'][Math.round(bearing/45)%8];updateLabels();radar();}
function radar(){const ctx=$('radar').getContext('2d');ctx.clearRect(0,0,160,160);ctx.strokeStyle='#dec59644';ctx.lineWidth=1;ctx.beginPath();ctx.arc(80,80,53,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(80,9);ctx.lineTo(80,151);ctx.moveTo(9,80);ctx.lineTo(151,80);ctx.stroke();function point(x,z,c,size){let dx=(x-player.position.x)*.4,dz=(z-player.position.z)*.4;let px=dx*Math.cos(yaw)-dz*Math.sin(yaw),py=dx*Math.sin(yaw)+dz*Math.cos(yaw);let l=Math.hypot(px,py);if(l>70){px*=70/l;py*=70/l;}ctx.fillStyle=c;ctx.fillRect(80+px-size/2,80+py-size/2,size,size);}forts.forEach((f,i)=>point(f.x,f.z,progress.captured.includes(i)?'#70d8ef':'#f4c986',5));enemies.forEach(e=>point(e.g.position.x,e.g.position.z,'#e77f5d',4));ctx.fillStyle='#b6f0fc';ctx.beginPath();ctx.moveTo(80,74);ctx.lineTo(76,85);ctx.lineTo(84,85);ctx.fill();}
const startTime=performance.now();let last=startTime,accumulator=0,uiTimer=0,frameTimes=[],frameCount=0;camera.position.set(5,9,31);camera.lookAt(0,6,0);updateUI();$('loading').hidden=true;
function tick(now){requestAnimationFrame(tick);const raw=Math.min((now-last)/1000,.5);last=now;realElapsed+=raw;frameTimes.push(raw);if(frameTimes.length>180)frameTimes.shift();autoFrames++;autoSeconds+=raw;autoTimer+=raw;if(autoTimer>6&&qualitySelection==='auto'){if(autoSeconds/autoFrames>.04&&resolutionScale>.48){resolutionScale=Math.max(.45,resolutionScale-.13);renderer.setPixelRatio(Math.min(devicePixelRatio,resolutionScale));if(qualityName!=='low'){qualityName='low';renderer.shadowMap.enabled=false;worldQuality('low');}}autoTimer=0;autoFrames=0;autoSeconds=0;}
 const stopped=hitStop>0;hitStop=Math.max(0,hitStop-raw);accumulator+=Math.min(raw,.25)*(stopped?.15:1);let steps=0;while(accumulator>=1/60&&steps<15){update(1/60);accumulator-=1/60;steps++;}const pull=grapple?1.4:charge>0?1.18:1;const f=forward(),right=new T.Vector3(-f.z,0,f.x);const desired=player.position.clone().addScaledVector(f,-23*pull).addScaledVector(right,-10);desired.y=player.position.y+8+pitch*18;desired.y=Math.max(desired.y,groundHeight(desired.x,desired.z)+3);camera.position.lerp(desired,1-Math.exp(-raw*5));shake*=Math.exp(-raw*7);kick*=Math.exp(-raw*8);camera.position.x+=(rand()-.5)*shake;camera.position.y+=(rand()-.5)*shake;camera.lookAt(player.position.clone().addScaledVector(f,grapple?6:10).add(new T.Vector3(0,6-kick,0)));camera.fov=T.MathUtils.lerp(camera.fov,charge>0?63:57,1-Math.exp(-raw*8));camera.updateProjectionMatrix();sun.position.set(player.position.x-95,player.position.y+65,player.position.z-100);sun.target.position.copy(player.position);hurt=Math.max(0,hurt-raw*1.5);$('hurt').style.opacity=hurt;uiTimer+=raw;if(uiTimer>.1){uiTimer=0;updateUI();}particlesTick(Math.min(raw,.25));renderer.render(scene,camera);frameCount++;}

